/*
 * Case-study page — case-studies/<slug>.html (generated by `npm run build`).
 * The page arrives fully rendered; this only re-renders it if the data in
 * data/case-studies.js changed after the last build. Slug: <body data-slug>.
 */
(function () {
  const root = document.querySelector('[data-render="case-study"]');
  const slug = document.body.dataset.slug;
  if (root && slug) window.RENDER.hydrate(root, window.RENDER.caseStudy(slug));
})();
